// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // Fuzz parameter: whether the callee should revert (true) or succeed (false).
    // The general rule: C.forward(...) returns (does not revert) iff the low-level call to callee succeeds.
    // The mutant inverts the success flag, so for a callee that reverts or succeeds we can distinguish.
    function testFuzz_property(bool calleeReverts) public {
        // deploy a callee that either reverts or succeeds based on the boolean
        CalleeRecorder callee = new CalleeRecorder(calleeReverts);

        // call c.forward and observe whether it reverts via try/catch
        bool ok;
        try c.forward(address(callee), "0x") {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract's general rule: forward returns (ok == true) exactly when the low-level call succeeded.
        // Our callee encodes the low-level call outcome in calleeReverts: if calleeReverts==true, the low-level call will revert (so ok must be false);
        // if calleeReverts==false, the low-level call will succeed (so ok must be true).
        // This assertion is true for the reference implementation for all inputs, and false for the mutant when calleeReverts==false (or true) depending on inversion.
        assertTrue(ok != calleeReverts);
    }
}

// Adversarial/observing callee: if shouldRevert is true, its fallback reverts; else it accepts and does nothing.
contract CalleeRecorder {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    // fallback will be invoked by low-level call from C.forward
    fallback() external payable {
        if (shouldRevert) {
            revert("I revert as instructed");
        }
        // succeed silently otherwise
    }
    receive() external payable {
        if (shouldRevert) {
            revert("I revert as instructed");
        }
    }
}
